@keyframes fadeInUp { from { opacity: 0; transform: translateY(20px); } to { opacity: 1; transform: translateY(0); } }
  @keyframes floatDelayed { 0%, 100% { transform: translate(-3rem, -2rem) rotate(-15deg); } 50% { transform: translate(-3rem, -2.5rem) rotate(-10deg); } }
  @keyframes float { 0%, 100% { transform: translateY(0) rotate(0deg); } 50% { transform: translateY(-15px) rotate(2deg); } }
  
  .animate-fade-in-up { animation: fadeInUp 0.6s cubic-bezier(0.16, 1, 0.3, 1) forwards; }
  .animate-float { animation: float 6s ease-in-out infinite; }
  .animate-float-delayed { animation: floatDelayed 7s ease-in-out infinite; }
  
  .perspective-1000 { perspective: 1000px; }
  ::-webkit-scrollbar { width: 6px; }
  ::-webkit-scrollbar-track { background: transparent; }
  ::-webkit-scrollbar-thumb { background: #cbd5e1; border-radius: 4px; }
  
  .scrollbar-hide::-webkit-scrollbar { display: none; }
  .scrollbar-hide { -ms-overflow-style: none; scrollbar-width: none; }
